import java.util.*

class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "Capacity must be at least 1, got: $capacity" }
    }

    private data class Entry<V>(val key: Any, var value: V)

    private val cache = object : LinkedHashMap<Any, Entry<V>>(capacity * 2, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<Any, Entry<V>>?): Boolean {
            if (size > capacity && eldest != null) {
                val entry = eldest.value
                onEvict(entry.key as K, entry.value)
            }
            return size > capacity
        }
    }

    operator fun get(key: K): V? {
        val entry = cache[key as Any]
        return entry?.value
    }

    operator fun set(key: K, value: V) {
        cache[key as Any] = Entry(key, value)
    }

    fun remove(key: K): V? {
        val entry = cache.remove(key as Any)
        return entry?.value
    }

    val size: Int get() = cache.size

    fun keys(): List<K> {
        // LinkedHashMap with access-order=true returns entries from least to most recently accessed
        return cache.keys.map { it as K }
    }

    operator fun contains(key: K): Boolean {
        // Avoid calling get/containsKey which would update access order
        return cache.entries.any { it.key == key as Any }
    }
}
