            sb.append(": ")
            sb.append(serialize(value, indent, level + 1))
        }

        sb.append('\n')
        sb.append(indentLevel)
        sb.append('}')

        return sb.toString()
    }
}

private fun serializeList(list: List<*>, indent: Int, level: Int): String {
    if (list.isEmpty()) return "[]"

    if (indent == 0) {
        val sb = StringBuilder()
        sb.append('[')
        var first = true
        for (item in list) {
            if (!first) sb.append(',')
            first = false
            sb.append(serialize(item, indent, level))
        }
        sb.append(']')
        return sb.toString()
    } else {
        val sb = StringBuilder()
        val innerIndent = " ".repeat(indent)
        val indentLevel = " ".repeat(level * indent)
        val nextIndentLevel = " ".repeat((level + 1) * indent)

        sb.append('[')
        sb.append('\n')

        var first = true
        for (item in list) {
            if (!first) {
                sb.append(',')
                sb.append('\n')
            }
            first = false
            sb.append(nextIndentLevel)
            sb.append(serialize(item, indent, level + 1))
        }

        sb.append('\n')
        sb.append(indentLevel)
        sb.append(']')

        return sb.toString()
    }
}

private fun serializeArray(array: Array<*>, indent: Int, level: Int): String {
    if (array.isEmpty()) return "[]"

    if (indent == 0) {
        val sb = StringBuilder()
        sb.append('[')
        var first = true
        for (item in array) {
            if (!first) sb.append(',')
            first = false
            sb.append(serialize(item, indent, level))
        }
        sb.append(']')
        return sb.toString()
    } else {
        val sb = StringBuilder()
        val innerIndent = " ".repeat(indent)
        val indentLevel = " ".repeat(level * indent)
        val nextIndentLevel = " ".repeat((level + 1) * indent)

        sb.append('[')
        sb.append('\n')

        var first = true
        for (item in array) {
            if (!first) {
                sb.append(',')
                sb.append('\n')
            }
            first = false
            sb.append(nextIndentLevel)
            sb.append(serialize(item, indent, level + 1))
        }

        sb.append('\n')
        sb.append(indentLevel)
        sb.append(']')

        return sb.toString()
    }
}

private fun escapeString(s: String): String {
    val sb = StringBuilder()
    sb.append('"')

    for (c in s) {
        when (c) {
            '\\' -> sb.append("\\\\")
            '"' -> sb.append("\\\"")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            '\b' -> sb.append("\\b")
            '\u000C' -> sb.append("\\f")
            else -> {
                if (c.code < 0x20) {
                    sb.append("\\u")
                    sb.append(String.format("%04x", c.code))
                } else {
                    sb.append(c)
                }
            }
        }
    }

    sb.append('"')
    return sb.toString()
}
