sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}
class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    var lastToken: Token? = null

    while (i < input.length) {
        // Skip whitespace
        if (input[i].isWhitespace()) {
            i++
            continue
        }

        val start = i
        val c = input[i]

        // Handle identifiers
        if (c.isLetter() || c == '_') {
            val sb = StringBuilder()
            while (i < input.length && 
                   (input[i].isLetterOrDigit() || input[i] == '_' || input[i] == '.')) {
                sb.append(input[i])
                i++
            }
            tokens.add(Token.Ident(sb.toString(), start))
            lastToken = tokens.last()
            continue
        }

        // Handle numbers (including negative numbers in valid positions)
        if (c.isDigit() || (c == '-' && canStartNegativeNumber(lastToken))) {
            // Check for negative number
            val isNegative = c == '-'
            if (isNegative) i++

            val numStart = i

            // Integer part
            while (i < input.length && input[i].isDigit()) i++

            // Fractional part
            var hasFraction = false
            if (i < input.length && input[i] == '.') {
                hasFraction = true
                i++

                // Must have at least one digit after the dot
                if (i == input.length || !input[i].isDigit()) {
                    throw TokenizeException("Invalid number format", start)
                }
                while (i < input.length && input[i].isDigit()) i++
            }

            // Must have at least one digit in total
            if (!hasFraction && i == numStart) {
                throw TokenizeException("Invalid number format", start)
            }

            val numStr = if (isNegative) "-${input.substring(numStart, i)}" else input.substring(numStart, i)
            tokens.add(Token.Num(numStr.toDouble(), start))
            lastToken = tokens.last()
            continue
        }

        // Handle strings
        if (c == '"' || c == '\'') {
            val quoteChar = c
            val sb = StringBuilder()
            i++

            while (i < input.length) {
                val ch = input[i]
                if (ch == '\\' && i + 1 < input.length) {
                    i++
                    val nextChar = input[i]
                    when (nextChar) {
                        'n' -> sb.append('\n')
                        't' -> sb.append('\t')
                        'r' -> sb.append('\r')
                        'b' -> sb.append('\b')
                        'f' -> sb.append('\u000C')
                        '\\' -> sb.append('\\')
                        '\'' -> sb.append('\'')
                        '"' -> sb.append('"')
                        else -> sb.append(nextChar)
                    }
                    i++
                } else if (ch == quoteChar) {
                    i++
                    tokens.add(Token.Str(sb.toString(), start))
                    lastToken = tokens.last()
                    break
                } else {
                    sb.append(ch)
                    i++
                }
            }

            // Check for unterminated string
            if (i >= input.length && input[i-1] != quoteChar) {
                throw TokenizeException("Unterminated string", start)
            }
            continue
        }

        // Handle parentheses
        if (c == '(') {
            tokens.add(Token.Paren(true, start))
            lastToken = tokens.last()
            i++
            continue
        }
        if (c == ')') {
            tokens.add(Token.Paren(false, start))
            lastToken = tokens.last()
            i++
            continue
        }

        // Handle operators
        val operators = listOf("==", "!=", "<=", ">=", "<", ">", "&&", "||", "!")
        for (op in operators) {
            if (input.startsWith(op, i)) {
                tokens.add(Token.Op(op, start))
                lastToken = tokens.last()
                i += op.length
                break
            }
        }
        if (lastToken is Token.Op && lastToken.pos == start) {
            continue
        }

        // If no pattern matched, throw exception
        throw TokenizeException("Unexpected character: '$c'", start)
    }

    return tokens
}

private fun canStartNegativeNumber(lastToken: Token?): Boolean {
    return lastToken == null || 
           lastToken is Token.Op || 
           lastToken is Token.Paren && lastToken.open
}
