                # Check for leading zeros (except for "0" itself)
                if part != str(index):
                    raise ValueError(f"Invalid list index '{part}' with leading zeros")

                # If this is the last part, set the value directly
                if is_last:
                    if isinstance(current, dict):
                        # Ensure there's a list for this key
                        if part not in current:
                            current[part] = []
                        elif not isinstance(current[part], list):
                            raise ValueError(f"Conflict: key '{key}' conflicts with existing key '{part}'")

                        # Expand list if needed and set value
                        while len(current[part]) <= index:
                            current[part].append(None)
                        current[part][index] = value
                    elif isinstance(current, list):
                        # Expand list if needed and set value
                        while len(current) <= index:
                            current.append(None)
                        current[index] = value
                    else:
                        raise ValueError(f"Conflict: key '{key}' conflicts with other paths")
                else:
                    # Need to navigate deeper
                    next_part = parts[i+1]
                    next_is_list_index = next_part.isdigit()

                    # Check if we need to create a list or dict
                    if next_is_list_index:
                        # Next part should be in a list
                        if isinstance(current, dict):
                            if part not in current:
                                current[part] = []
                            elif not isinstance(current[part], list):
                                raise ValueError(f"Conflict: key '{key}' conflicts with existing key '{part}'")
                            current = current[part]
                        elif isinstance(current, list):
                            while len(current) <= index:
                                current.append(None)
                            current = current[index]
                        else:
                            raise ValueError(f"Conflict: key '{key}' conflicts with other paths")
                    else:
                        # Next part should be in a dict
                        if isinstance(current, dict):
                            if part not in current:
                                current[part] = {}
                            elif not isinstance(current[part], dict):
                                raise ValueError(f"Conflict: key '{key}' conflicts with existing key '{part}'")
                            current = current[part]
                        elif isinstance(current, list):
                            while len(current) <= index:
                                current.append(None)
                            current = current[index]
                        else:
                            raise ValueError(f"Conflict: key '{key}' conflicts with other paths")
            else:
                # Regular string key
                if is_last:
                    if isinstance(current, dict):
                        # Check if there's already a list or something else here
                        if part in current:
                            existing = current[part]
                            # Allow overwriting with same value but not conflicting types
                            if not (existing == value or 
                                    (isinstance(existing, (dict, list)) and 
                                     isinstance(value, (dict, list)))):
                                raise ValueError(f"Conflict: key '{key}' conflicts with existing key '{part}'")
                        current[part] = value
                    elif isinstance(current, list):
                        raise ValueError(f"Conflict: key '{key}' conflicts with list path")
                    else:
                        raise ValueError(f"Conflict: key '{key}' conflicts with other paths")
                else:
                    # Need to create a dict for the next level
                    if isinstance(current, dict):
                        if part not in current:
                            current[part] = {}
                        elif not isinstance(current[part], dict):
                            raise ValueError(f"Conflict: key '{key}' conflicts with existing key '{part}'")
                        current = current[part]
                    elif isinstance(current, list):
                        # This shouldn't happen in normal cases, but handle it
                        index = int(parts[i-1])
                        while len(current) <= index:
                            current.append(None)
                        current = current[index]
                    else:
                        raise ValueError(f"Conflict: key '{key}' conflicts with other paths")

    # Validate that all lists are dense (0..n-1)
    def _check_dense(obj, path=""):
        if isinstance(obj, dict):
            for key, value in obj.items():
                _check_dense(value, f"{path}.{key}" if path else key)
        elif isinstance(obj, list):
            # Check that the list is dense
            for i, item in enumerate(obj):
                if item is None:
                    raise ValueError(f"Non-dense list at path '{path}': missing index {i}")

    _check_dense(result)

    return result
