def flatten(obj, sep="."):
    """
    Flatten a nested dictionary and list structure into a flat dictionary with path keys.

    Args:
        obj: The object to flatten (must be a dict)
        sep: The separator to use between path segments (default: ".")

    Returns:
        A flat dictionary with path keys

    Raises:
        TypeError: If obj is not a dict
        ValueError: If any key contains the separator or if there are invalid keys
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(current_obj, path_parts):
        # If it's a dict
        if isinstance(current_obj, dict):
            # Iterate through keys in order
            for key, value in current_obj.items():
                # Check if key is a string and doesn't contain separator
                if not isinstance(key, str):
                    raise ValueError("All keys must be strings")
                if sep in key:
                    raise ValueError(f"Key '{key}' contains separator '{sep}'")

                # Create new path
                new_path = path_parts + [key]

                # If value is a dict
                if isinstance(value, dict):
                    # Check if dict is empty - keep it as leaf
                    if not value:
                        result[sep.join(new_path)] = {}
                    else:
                        _flatten(value, new_path)
                # If value is a list
                elif isinstance(value, list):
                    # Check if list is empty - keep it as leaf
                    if not value:
                        result[sep.join(new_path)] = []
                    else:
                        # Process list elements
                        for i, item in enumerate(value):
                            list_path = new_path + [str(i)]

                            if isinstance(item, dict):
                                # If dict is empty, keep it as leaf
                                if not item:
                                    result[sep.join(list_path)] = {}
                                else:
                                    _flatten(item, list_path)
                            elif isinstance(item, list):
                                # If list is empty, keep it as leaf
                                if not item:
                                    result[sep.join(list_path)] = []
                                else:
                                    _flatten(item, list_path)
                            else:
                                # Any other value is a leaf
                                result[sep.join(list_path)] = item
                else:
                    # Any other value is a leaf
                    result[sep.join(new_path)] = value

    # Start flattening with empty path
    _flatten(obj, [])
    return result


def unflatten(flat, sep="."):
    """
    Unflatten a flat dictionary with path keys into a nested structure.

    Args:
        flat: The flat dictionary to unflatten
        sep: The separator used in path keys (default: ".")

    Returns:
        A nested dictionary/list structure

    Raises:
        ValueError: If there are conflicts, invalid list indices, or non-dense lists
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # Group paths by their prefixes to detect conflicts
    # First, collect all paths and sort by length to process shorter paths first
    paths = []
    for key, value in flat.items():
        parts = key.split(sep)
        paths.append((parts, value))

    # Sort by path length to process shorter paths first
    paths.sort(key=lambda x: len(x[0]))

    result = {}

    # Helper to get or create a node at a path
    for parts, value in paths:
        current = result
        for i, part in enumerate(parts):
            is_last = (i == len(parts) - 1)

            # Check if part is a list index (non-negative integer without leading zeros)
            is_list_index = part.isdigit()
            if is_list_index and part != "0" and part.startswith("0"):
                raise ValueError(f"Invalid list index '{part}' with leading zeros")

            if is_last:
                # Set the value
                if is_list_index:
                    index = int(part)
                    if isinstance(current, dict):
                        if part not in current:
                            current[part] = []
                        elif not isinstance(current[part], list):
                            raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with existing key '{part}'")
                        # Expand list if needed
                        while len(current[part]) <= index:
                            current[part].append(None)
                        current[part][index] = value
                    elif isinstance(current, list):
                        while len(current) <= index:
                            current.append(None)
                        current[index] = value
                    else:
                        raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with other paths")
                else:
                    if isinstance(current, dict):
                        if part in current:
                            existing = current[part]
                            # Allow same values but not conflicting structures
                            if not (existing == value):
                                raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with existing key '{part}'")
                        current[part] = value
                    elif isinstance(current, list):
                        raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with list path")
                    else:
                        raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with other paths")
            else:
                next_part = parts[i+1]
                next_is_list_index = next_part.isdigit()
                if next_part != "0" and next_part.startswith("0"):
                    raise ValueError(f"Invalid list index '{next_part}' with leading zeros")

                if is_list_index:
                    index = int(part)
                    # Expand list if needed
                    if isinstance(current, dict):
                        if part not in current:
                            current[part] = []
                        elif not isinstance(current[part], list):
                            raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with existing key '{part}'")
                        current = current[part]
                    elif isinstance(current, list):
                        while len(current) <= index:
                            current.append(None)
                        current = current[index]
                    else:
                        raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with other paths")
                else:
                    # Regular string key - create dict for next level
                    if isinstance(current, dict):
                        if part not in current:
                            current[part] = {}
                        elif not isinstance(current[part], dict):
                            raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with existing key '{part}'")
                        current = current[part]
                    elif isinstance(current, list):
                        while len(current) <= index:
                            current.append(None)
                        current = current[index]
                    else:
                        raise ValueError(f"Conflict: key '{sep.join(parts)}' conflicts with other paths")

    # Validate that all lists are dense (0..n-1)
    def _check_dense(obj, path=""):
        if isinstance(obj, dict):
            for key, value in obj.items():
                _check_dense(value, f"{path}.{key}" if path else key)
        elif isinstance(obj, list):
            # Check that all indices 0..n-1 are present and not None
            for i in range(len(obj)):
                if i >= len(obj) or obj[i] is None:
                    raise ValueError(f"Non-dense list at path '{path}': missing index {i}")

            # Check all items are valid (not None)
            for i, item in enumerate(obj):
                if item is None:
                    raise ValueError(f"Non-dense list at path '{path}': missing index {i}")

    _check_dense(result)

    return result
