import re
from typing import Union

def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if env is None:
        env = {}

    # Tokenize the expression
    tokens = _tokenize(expr)
    if not tokens:
        raise SyntaxError("Empty expression")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def match(*types):
        return peek() and peek()[0] in types

    def parse_expression():
        return parse_conditional()

    def parse_conditional():
        """Parse ternary operator: a ? b : c (right-associative)"""
        expr = parse_logical_or()

        if match('?'):
            consume()  # consume '?'
            true_expr = parse_conditional()
            if not match(':'):
                raise SyntaxError("Missing ':' in conditional expression")
            consume()  # consume ':'
            false_expr = parse_conditional()
            # Only evaluate the chosen branch
            return true_expr if expr else false_expr
        return expr

    def parse_logical_or():
        left = parse_logical_and()

        while match('||'):
            consume()
            # Short-circuit: if left is truthy (non-zero), don't evaluate right
            if left:
                # Still need to parse the right expression for syntax validation
                right = parse_logical_and()
            else:
                right = parse_logical_and()
                left = right

            # Actually evaluate with short-circuit semantics
            left = 1 if left else (1 if right else 0)

        return left

    def parse_logical_and():
        left = parse_comparison()

        while match('&&'):
            consume()
            # Short-circuit: if left is falsy (zero), don't evaluate right
            if not left:
                # Still need to parse the right expression for syntax validation
                right = parse_comparison()
            else:
                right = parse_comparison()
                left = right

            # Actually evaluate with short-circuit semantics
            left = 1 if left and right else 0

        return left

    def parse_comparison():
        left = parse_additive()

        while match('==', '!=', '<', '<=', '>', '>='):
            op = consume()
            right = parse_additive()

            if op == '==':
                result = 1 if left == right else 0
            elif op == '!=':
                result = 1 if left != right else 0
            elif op == '<':
                result = 1 if left < right else 0
            elif op == '<=':
                result = 1 if left <= right else 0
            elif op == '>':
                result = 1 if left > right else 0
            elif op == '>=':
                result = 1 if left >= right else 0

            left = result

        return left

    def parse_additive():
        left = parse_multiplicative()

        while match('+', '-'):
            op = consume()
            right = parse_multiplicative()

            if op == '+':
                left = left + right
            else:  # op == '-'
                left = left - right

        return left

    def parse_multiplicative():
        left = parse_unary()

        while match('*', '/', '%'):
            op = consume()
            right = parse_unary()

            if op == '*':
                left = left * right
            elif op == '/':
                # Check division by zero
                if right == 0:
                    raise ZeroDivisionError("Division by zero")

                # For two integers, if exact division, return int, else float
                if isinstance(left, int) and isinstance(right, int):
                    result = left / right
                    if result.is_integer():
                        left = int(result)
                    else:
                        left = result
                else:
                    left = left / right
            else:  # op == '%'
                # Check modulo by zero
                if right == 0:
                    raise ZeroDivisionError("Modulo by zero")

                # Follow Python semantics for modulo
                left = left % right

        return left

    def parse_unary():
        if match('-', '+', '!'):
            op = consume()
            operand = parse_unary()  # recursive call handles multiple unary operators

            if op == '-':
                return -operand
            elif op == '+':
                return +operand
            else:  # op == '!'
                return 1 if operand == 0 else 0

        return parse_power()

    def parse_power():
        left = parse_primary()

        while match('^'):
            consume()
            # Power is right-associative, so parse the next power expression recursively
            # But for the right side, we need to handle unary operators (e.g., 2^-1)
            # We use parse_unary for the right side to allow unary operators
            right = parse_unary()

            left = left ** right

        return left

    def parse_primary():
        token = peek()

        if token is None:
            raise SyntaxError("Unexpected end of expression")

        token_type, value = token

        if token_type == 'number':
            consume()
            # Return as int or float
            if '.' in value:
                return float(value)
            else:
                return int(value)
        elif token_type == 'identifier':
            consume()
            # Check for function call
            if match('('):
                return parse_function_call(value)
            else:
                # Variable lookup
                if value not in env:
                    raise NameError(f"Undefined variable '{value}'")
                return env[value]
        elif token_type == '(':
            consume()  # consume '('
            expr = parse_expression()
            if not match(')'):
                raise SyntaxError("Missing closing parenthesis")
            consume()  # consume ')'
            return expr
        elif token_type in ('-', '+', '!'):
            # Handle as unary in parse_unary
            raise SyntaxError("Unexpected unary operator in primary")
        else:
            raise SyntaxError(f"Unexpected token: {token}")

    def parse_function_call(name):
        if name not in ('min', 'max', 'abs'):
            raise NameError(f"Undefined function '{name}'")

        consume()  # consume '('

        if not match('number', 'identifier', '(', '-', '+', '!'):
            raise SyntaxError("Empty function arguments")

        args = []
        while True:
            args.append(parse_expression())

            if match(')'):
                consume()  # consume ')'
                break
            elif match(','):
                consume()  # consume ','
            else:
                raise SyntaxError("Missing ',' or ')' in function arguments")

        # Check argument counts
        if name == 'abs':
            if len(args) != 1:
                raise SyntaxError(f"abs() requires exactly 1 argument, got {len(args)}")
            return abs(args[0])
        elif name == 'min':
            if len(args) == 0:
                raise SyntaxError("min() requires at least 1 argument")
            result = args[0]
            for arg in args[1:]:
                if arg < result:
                    result = arg
            return result
        elif name == 'max':
            if len(args) == 0:
                raise SyntaxError("max() requires at least 1 argument")
            result = args[0]
            for arg in args[1:]:
                if arg > result:
                    result = arg
            return result

    def _tokenize(expr: str):
        tokens = []
        i = 0

        while i < len(expr):
            # Skip whitespace
            if expr[i].isspace():
                i += 1
                continue

            # Check for multi-character tokens first
            if i + 1 < len(expr) and expr[i:i+2] in ('==', '!=', '<=', '>=', '&&', '||'):
                tokens.append((expr[i:i+2], expr[i:i+2]))
                i += 2
                continue

            # Check for single-character tokens
            if expr[i] in '()*,+-/%^!?&|':
                token = expr[i]
                # Check for standalone =, &, | that are not part of ==, !=, <=, >=, &&, ||
                if token == '=' or token == '&' or token == '|':
                    # Check it's not part of a longer token
                    if i + 1 < len(expr) and expr[i+1] in ('=', '&', '|'):
                        # These are handled above, so shouldn't reach here
                        raise SyntaxError(f"Invalid token '{token}'")
                    else:
                        # Standalone =, &, | is an error
                        if token == '=':
                            raise SyntaxError("Lone '=' is invalid")
                        elif token == '&':
                            raise SyntaxError("Lone '&' is invalid")
                        else:  # token == '|'
                            raise SyntaxError("Lone '|' is invalid")

                tokens.append((token, token))
                i += 1
                continue

            # Check for numbers (including decimals)
            if expr[i].isdigit() or (expr[i] == '.' and i + 1 < len(expr) and expr[i+1].isdigit()):
                j = i
                has_dot = False
                while j < len(expr) and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                    if expr[j] == '.':
                        has_dot = True
                    j += 1

                # Handle edge case like "2." or ".5"
                num_str = expr[i:j]
                if num_str == '.':
                    raise SyntaxError("Invalid number '.'")

                tokens.append(('number', num_str))
                i = j
                continue

            # Check for identifiers
            if expr[i].isalpha() or expr[i] == '_':
                j = i
                while j < len(expr) and (expr[j].isalnum() or expr[j] == '_'):
                    j += 1

                identifier = expr[i:j]
                tokens.append(('identifier', identifier))
                i = j
                continue

            # Unknown character
            raise SyntaxError(f"Unknown character '{expr[i]}'")

        return tokens

    # Start parsing
    result = parse_expression()

    # Check for trailing tokens
    if pos < len(tokens):
        raise SyntaxError(f"Unexpected token '{tokens[pos][0]}'")

    return result
