import re
from functools import cmp_to_key
from typing import List, Optional, Tuple, Union


class Version:
    def __init__(self, major: int, minor: int, patch: int, 
                 prerelease: Optional[List[Union[int, str]]] = None,
                 build: Optional[List[str]] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease or []
        self.build = build or []

    def __repr__(self):
        prerelease_str = f"-{'.'.join(str(p) for p in self.prerelease)}" if self.prerelease else ""
        build_str = f"+{'.'.join(self.build)}" if self.build else ""
        return f"Version({self.major}.{self.minor}.{self.patch}{prerelease_str}{build_str})"

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        return (self.major == other.major and 
                self.minor == other.minor and 
                self.patch == other.patch and 
                self.prerelease == other.prerelease)

    def __lt__(self, other):
        return compare_versions(self, other) < 0

    def __le__(self, other):
        return compare_versions(self, other) <= 0

    def __gt__(self, other):
        return compare_versions(self, other) > 0

    def __ge__(self, other):
        return compare_versions(self, other) >= 0

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease)))


def compare_versions(v1: Version, v2: Version) -> int:
    """Compare two Version objects according to SemVer precedence."""
    # Compare major, minor, patch first
    if v1.major != v2.major:
        return -1 if v1.major < v2.major else 1
    if v1.minor != v2.minor:
        return -1 if v1.minor < v2.minor else 1
    if v1.patch != v2.patch:
        return -1 if v1.patch < v2.patch else 1

    # Compare prerelease
    # A version without prerelease is greater than one with prerelease
    if not v1.prerelease and v2.prerelease:
        return 1
    if v1.prerelease and not v2.prerelease:
        return -1
    if not v1.prerelease and not v2.prerelease:
        return 0

    # Both have prerelease - compare identifier lists
    for i in range(min(len(v1.prerelease), len(v2.prerelease))):
        p1, p2 = v1.prerelease[i], v2.prerelease[i]
        # If both are integers, compare numerically
        if isinstance(p1, int) and isinstance(p2, int):
            if p1 < p2:
                return -1
            if p1 > p2:
                return 1
        # If one is integer and other is string, integer is less
        elif isinstance(p1, int) and not isinstance(p2, int):
            return -1
        elif not isinstance(p1, int) and isinstance(p2, int):
            return 1
        else:  # Both are strings
            if p1 < p2:
                return -1
            if p1 > p2:
                return 1

    # If all compared identifiers are equal, shorter list is smaller
    if len(v1.prerelease) < len(v2.prerelease):
        return -1
    if len(v1.prerelease) > len(v2.prerelease):
        return 1

    return 0


def parse_version_string(s: str) -> Version:
    """Parse a version string and return a Version object."""
    # Remove leading v or = if present
    s = s.strip()
    if s.startswith(('v', '=')):
        s = s[1:]
    s = s.strip()

    # Build metadata regex
    build_metadata_pattern = r'\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)$'
    build_match = re.search(build_metadata_pattern, s)
    build = []
    if build_match:
        build = build_match.group(1).split('.')
        s = s[:build_match.start()]

    # Prerelease regex
    prerelease_pattern = r'-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)$'
    prerelease_match = re.search(prerelease_pattern, s)
    prerelease = []
    if prerelease_match:
        prerelease_parts = prerelease_match.group(1).split('.')
        for part in prerelease_parts:
            # Check if it's numeric (no leading zeros unless it's just "0")
            if re.match(r'^[0-9]+$', part):
                if len(part) > 1 and part[0] == '0':
                    raise ValueError(f"Invalid version: leading zeros in numeric identifier '{part}'")
                prerelease.append(int(part))
            elif re.match(r'^[0-9A-Za-z-]+$', part):
                prerelease.append(part)
            else:
                raise ValueError(f"Invalid version: invalid prerelease identifier '{part}'")
        s = s[:prerelease_match.start()]

    # Main version regex
    version_pattern = r'^([0-9]+)\.([0-9]+)\.([0-9]+)$'
    match = re.match(version_pattern, s)
    if not match:
        raise ValueError(f"Invalid version: '{s}'")

    major_str, minor_str, patch_str = match.groups()

    # Check for leading zeros
    if (len(major_str) > 1 and major_str[0] == '0') or \
       (len(minor_str) > 1 and minor_str[0] == '0') or \
       (len(patch_str) > 1 and patch_str[0] == '0'):
        raise ValueError(f"Invalid version: leading zeros in numeric identifier")

    return Version(
        int(major_str),
        int(minor_str),
        int(patch_str),
        prerelease if prerelease else None,
        build if build else None
    )


def parse(v: str) -> Version:
    """Parse a version string according to SemVer 2.0.0."""
    try:
        return parse_version_string(v)
    except ValueError as e:
        raise ValueError(f"Invalid version: {str(e)}") from e


def compare_prerelease_identifiers(id1: Union[int, str], id2: Union[int, str]) -> int:
    """Compare two prerelease identifiers according to SemVer rules."""
    # If both are integers, compare numerically
    if isinstance(id1, int) and isinstance(id2, int):
        if id1 < id2:
            return -1
        elif id1 > id2:
            return 1
        return 0

    # If one is integer and other is string, integer is less
    if isinstance(id1, int) and not isinstance(id2, int):
        return -1

    if not isinstance(id1, int) and isinstance(id2, int):
        return 1

    # Both are strings - compare ASCII order
    if id1 < id2:
        return -1
    elif id1 > id2:
        return 1

    return 0


def compare_prerelease_lists(pr1: List[Union[int, str]], pr2: List[Union[int, str]]) -> int:
    """Compare two prerelease lists."""
    # Empty prerelease list means release version
    if not pr1 and not pr2:
        return 0
    if not pr1 and pr2:
        return 1  # Release > prerelease
    if pr1 and not pr2:
        return -1  # Prerelease < release

    # Both have prerelease - compare identifier lists
    min_len = min(len(pr1), len(pr2))
    for i in range(min_len):
        cmp = compare_prerelease_identifiers(pr1[i], pr2[i])
        if cmp != 0:
            return cmp

    # If all compared identifiers are equal, shorter list is smaller
    if len(pr1) < len(pr2):
        return -1
    if len(pr1) > len(pr2):
        return 1

    return 0


def compare_versions_for_satisfies(v1: Version, v2: Version) -> int:
    """Compare two versions ignoring build metadata."""
    # Compare major, minor, patch first
    if v1.major != v2.major:
        return -1 if v1.major < v2.major else 1
    if v1.minor != v2.minor:
        return -1 if v1.minor < v2.minor else 1
    if v1.patch != v2.patch:
        return -1 if v1.patch < v2.patch else 1

    # Compare prerelease
    cmp = compare_prerelease_lists(v1.prerelease, v2.prerelease)
    return cmp


