    """Parse a partial version string into (major, minor, patch)."""
    s = s.strip()

    # Handle wildcards
    if s == '*' or s.lower() == 'x':
        return (0, 0, 0)

    parts = s.split('.')
    if len(parts) > 3:
        raise ValueError(f"Invalid partial version: '{s}'")

    # Replace wildcards with 0
    major = 0
    minor = 0
    patch = 0

    try:
        if parts[0] == '*' or parts[0].lower() == 'x':
            major = 0
