            major = int(parts[0])

        if len(parts) > 1:
            if parts[1] == '*' or parts[1].lower() == 'x':
                minor = 0
            else:
                minor = int(parts[1])
        else:
            minor = 0

        if len(parts) > 2:
            if parts[2] == '*' or parts[2].lower() == 'x':
                patch = 0
            else:
                patch = int(parts[2])
        else:
            patch = 0

        # Validate no leading zeros (except for 0 itself)
        def validate_numeric(s_val):
            if s_val == '':
                return 0
            if re.match(r'^0$', s_val):
                return 0
            if re.match(r'^0[0-9]+$', s_val):
                raise ValueError(f"Invalid partial version: leading zeros in '{s_val}'")
            return int(s_val)

        major = validate_numeric(parts[0])
        if len(parts) > 1 and parts[1] not in ('*', 'x'):
            minor = validate_numeric(parts[1])
        if len(parts) > 2 and parts[2] not in ('*', 'x'):
            patch = validate_numeric(parts[2])

    except (ValueError, IndexError):
        raise ValueError(f"Invalid partial version: '{s}'")

    return (major, minor, patch)


