        """A range is a list of comparators that must all be satisfied."""
        self.comparators = comparators

    def satisfies(self, version: Version) -> bool:
        """Check if the version satisfies all comparators in this range."""
        for op, v, is_partial, _, _, _, _, minor_wildcard, patch_wildcard in self.comparators:
