    def __init__(self, ranges: List[Range]):
        """A comparator set is a list of ranges joined by ||."""
        self.ranges = ranges

    def satisfies(self, version: Version) -> bool:
        """Check if the version satisfies any of the ranges in this set."""
        return any(r.satisfies(version) for r in self.ranges)


