                        upper_inclusive = Version(major_upper, minor_upper, patch_upper)
                        range_obj = Range([lower_inclusive])
                    else:
                        lower_inclusive = Version(major_lower, minor_lower, patch_lower)
                        upper_inclusive = Version(major_upper, minor_upper, patch_upper)
