                        ('<=', upper_inclusive, False, 0, 0, 0, False, False)
                    ])

                ranges.append(range_obj)

            else:
                # Regular comparator
                op, version, is_partial = parse_comparator_with_wildcards(part)

                # Extract major, minor, patch
                major = version.major
                minor = version.minor
                patch = version.patch

                # Check for wildcards in original string
                parts = part.split('.')
                minor_wildcard = len(parts) > 1 and (parts[1] == '*' or parts[1].lower() == 'x')
                patch_wildcard = len(parts) > 2 and (parts[2] == '*' or parts[2].lower() == 'x')

                # For operators like >, >=, <, <= with partial versions, we need to expand
                if op in ('>', '<', '>=', '<=') and is_partial:
                    # Expand to range based on operator and partial version

                    # Handle tilde and caret later - they're special operators

                    # For now, handle basic operators
                    if op == '>=':
                        # >=1.2 means >=1.2.0
                        range_obj = Range([
                            ('>=', version, is_partial, major, minor, patch, minor_wildcard, patch_wildcard)
                        ])
                    elif op == '>':
                        # >1.2 means >=1.3.0
                        if minor_wildcard and patch_wildcard:
                            # >1 means >=2.0.0
                            next_version = Version(major + 1, 0, 0)
                        elif minor_wildcard:
                            # >1.2 means >=1.3.0
                            next_version = Version(major, minor + 1, 0)
                        else:
                            # >1.2.3 means >=1.2.4
                            next_version = Version(major, minor, patch + 1)
                        range_obj = Range([
                            ('>=', next_version, False, 0, 0, 0, False, False)
                        ])
                    elif op == '<=':
                        # <=1.2 means <1.3.0, i.e., <=1.2.999...
                        # We can represent this as < next version
                        if minor_wildcard and patch_wildcard:
                            # <=1 means <2.0.0
                            upper_exclusive = Version(major + 1, 0, 0)
                        elif minor_wildcard:
                            # <=1.2 means <1.3.0
                            upper_exclusive = Version(major, minor + 1, 0)
                        else:
                            # <=1.2.3 means <1.2.4
                            upper_exclusive = Version(major, minor, patch + 1)
                        range_obj = Range([
                            ('<', upper_exclusive, False, 0, 0, 0, False, False)
                        ])
                    elif op == '<':
                        # <1.2 means <1.2.0
                        if minor_wildcard and patch_wildcard:
                            # <1 means <1.0.0, which is impossible for positive major
                            # But could be 0.x.x, so <1.0.0 means <1.0.0
                            upper_exclusive = Version(major, 0, 0)
                        elif minor_wildcard:
                            # <1.2 means <1.2.0
                            upper_exclusive = Version(major, minor, 0)
                        else:
                            # <1.2.3 means <1.2.3
                            upper_exclusive = version
                        range_obj = Range([
                            ('<', upper_exclusive, False, 0, 0, 0, False, False)
                        ])
                    else:
                        range_obj = Range([
                            (op, version, is_partial, major, minor, patch, minor_wildcard, patch_wildcard)
                        ])
                else:
                    range_obj = Range([
                        (op, version, is_partial, major, minor, patch, minor_wildcard, patch_wildcard)
                    ])

                ranges.append(range_obj)

        # Create comparator set from ranges
        comparator_set = ComparatorSet(ranges)
        comparator_sets.append(comparator_set)

    return comparator_sets


def patch_str_has_wildcard(s: str, index: int) -> bool:
    """Check if the part at the given index has a wildcard."""
    parts = s.split('.')
    if index >= len(parts):
        return False
    return parts[index] == '*' or parts[index].lower() == 'x'


def satisfies(version_str: str, rng: str) -> bool:
    """Check if a version satisfies a range."""
    version = parse(version_str)

    # Parse the range
    # First, handle special cases like '*'
    rng = rng.strip()
    if rng == '*':
        return True

    # Check for empty range
    if not rng:
        raise ValueError("Empty range")

    # Split into sets by ||
    set_strings = rng.split('||')

    for set_str in set_strings:
        set_str = set_str.strip()
        if not set_str:
            continue

        # Check for * in set
        if set_str == '*':
            return True

        # Split into comparators by whitespace
        parts = set_str.split()

        # Check for empty set
        if not parts:
            continue

        all_match = True
        for part in parts:
            part = part.strip()
            if not part:
                continue

            # Check for hyphen range
            if ' - ' in part:
                hyphen_parts = part.split(' - ')
                if len(hyphen_parts) != 2:
                    raise ValueError(f"Invalid hyphen range: '{part}'")

                lower_str = hyphen_parts[0].strip()
                upper_str = hyphen_parts[1].strip()

                if not lower_str or not upper_str:
                    raise ValueError(f"Invalid hyphen range: '{part}'")

                # Parse lower version
                lower_version = parse_version_string(lower_str)

                # Parse upper version
                upper_version = parse_version_string(upper_str)

                # For partial upper bound, it's exclusive of the next: "1.2.3 - 2.3" is <2.4.0
                major_upper = upper_version.major
                minor_upper = upper_version.minor
                patch_upper = upper_version.patch

                # Check for wildcards in upper version
                minor_wildcard_upper = 'x' in upper_str.lower() or '*' in upper_str
                patch_wildcard_upper = minor_wildcard_upper and patch_str_has_wildcard(upper_str, 2)

                if minor_wildcard_upper or patch_wildcard_upper:
                    # Expand upper bound to next version
                    if minor_upper == 0 and patch_upper == 0:
                        # e.g., 2 means next is 3.0.0
                        upper_exclusive = Version(major_upper + 1, 0, 0)
                    elif patch_upper == 0:
                        # e.g., 2.3 means next is 2.4.0
                        upper_exclusive = Version(major_upper, minor_upper + 1, 0)
                    else:
                        upper_exclusive = Version(major_upper, minor_upper, patch_upper + 1)

                    # Check if version >= lower and < upper_exclusive
                    if compare_versions_for_satisfies(version, lower_version) < 0:
                        all_match = False
                        break
                    if compare_versions_for_satisfies(version, upper_exclusive) >= 0:
                        all_match = False
                        break
                else:
                    # Exact upper bound, inclusive
                    # Check if version >= lower and <= upper
                    if compare_versions_for_satisfies(version, lower_version) < 0:
                        all_match = False
                        break
                    if compare_versions_for_satisfies(version, upper_version) > 0:
                        all_match = False
                        break
            else:
                # Regular comparator
                op = '='
                if part.startswith('>='):
                    op = '>='
                    version_part = part[2:]
                elif part.startswith('>'):
                    op = '>'
                    version_part = part[1:]
                elif part.startswith('<='):
                    op = '<='
                    version_part = part[2:]
                elif part.startswith('<'):
                    op = '<'
                    version_part = part[1:]
                else:
                    if part.startswith('='):
                        op = '='
                        version_part = part[1:]
                    else:
                        version_part = part

                version_part = version_part.strip()

                if not version_part:
                    raise ValueError("Invalid comparator: empty version")

                # Parse version
                comparator_version = parse_version_string(version_part)

                # Check for wildcards
                is_partial = 'x' in version_part.lower() or '*' in version_part

                # Handle partial versions
                if is_partial:
                    major = comparator_version.major
                    minor = comparator_version.minor
                    patch = comparator_version.patch

                    # Determine ranges based on operator
                    if op == '>=':
                        # >=1.2 means >=1.2.0
                        if compare_versions_for_satisfies(version, comparator_version) < 0:
                            all_match = False
                            break
                    elif op == '>':
                        # >1.2 means >=1.3.0
                        if minor == 0 and patch == 0:
                            if version.major <= major:
                                all_match = False
                                break
                        elif patch == 0:
                            if version.major < major or (version.major == major and version.minor <= minor):
                                all_match = False
                                break
                        else:
                            if version.major < major or \
                               (version.major == major and version.minor < minor) or \
                               (version.major == major and version.minor == minor and version.patch <= patch):
                                all_match = False
                                break
                    elif op == '<=':
                        # <=1.2 means <1.3.0, i.e., < next version after 1.2.x range
                        if minor == 0 and patch == 0:
                            if version.major >= major + 1:
                                all_match = False
                                break
                        elif patch == 0:
                            if version.major > major or (version.major == major and version.minor >= minor + 1):
                                all_match = False
                                break
                        else:
                            if version.major > major or \
                               (version.major == major and version.minor > minor) or \
                               (version.major == major and version.minor == minor and version.patch >= patch):
                                all_match = False
                                break
                    elif op == '<':
                        # <1.2 means <1.2.0
                        if minor == 0 and patch == 0:
                            if version.major >= major:
                                all_match = False
                                break
                        elif patch == 0:
                            if version.major > major or (version.major == major and version.minor >= minor):
                                all_match = False
                                break
                        else:
                            if compare_versions_for_satisfies(version, comparator_version) >= 0:
                                all_match = False
                                break
                    else:
                        # = with wildcards
                        if major != 0 and version.major != major:
                            all_match = False
                            break
                        if minor == 0 and patch == 0:
                            # 1 means >=1.0.0 <2.0.0
                            if version.major != major:
                                all_match = False
                                break
                        elif patch == 0:
                            # 1.2 means >=1.2.0 <1.3.0
                            if version.major != major or version.minor != minor:
                                all_match = False
                                break
                        else:
                            # 1.2.3 means exact match
                            if version.major != major or version.minor != minor or version.patch != patch:
                                all_match = False
                                break
                else:
                    # Exact version comparison
                    if op == '=':
                        if compare_versions_for_satisfies(version, comparator_version) != 0:
                            all_match = False
                            break
                    elif op == '<':
                        if compare_versions_for_satisfies(version, comparator_version) >= 0:
                            all_match = False
                            break
                    elif op == '>':
                        if compare_versions_for_satisfies(version, comparator_version) <= 0:
                            all_match = False
                            break
                    elif op == '<=':
                        if compare_versions_for_satisfies(version, comparator_version) > 0:
                            all_match = False
                            break
                    elif op == '>=':
                        if compare_versions_for_satisfies(version, comparator_version) < 0:
                            all_match = False
                            break
            # End if hyphen

        if all_match:
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the version that satisfies the range and is the highest."""
    satisfying_versions = []
    for v in versions:
        try:
            if satisfies(v, rng):
                satisfying_versions.append(v)
        except ValueError:
            # Skip invalid versions
            continue

    if not satisfying_versions:
        return None

    # Sort by version precedence and return the highest
    version_objects = []
    for v in satisfying_versions:
        try:
            version_objects.append((v, parse(v)))
        except ValueError:
            continue

    if not version_objects:
        return None

    # Sort by version in descending order
    version_objects.sort(key=lambda x: x[1], reverse=True)

    # Return the original string
    return version_objects[0][0]


def satisfies_version(version: Version, op: str, comparator_version: Version) -> bool:
    """Check if version satisfies the comparator."""
    cmp = compare_versions_for_satisfies(version, comparator_version)

    if op == '=':
        return cmp == 0
    elif op == '<':
        return cmp < 0
    elif op == '>':
        return cmp > 0
    elif op == '<=':
        return cmp <= 0
    elif op == '>=':
        return cmp >= 0

    return False


