def parse_v2(v: str) -> Version:
    """Parse a version string according to SemVer 2.0.0."""
    # Remove leading v or = if present
    s = v.strip()
    if s.startswith(('v', '=')):
        s = s[1:]
    s = s.strip()

    # Build metadata regex
    build_metadata_pattern = r'\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)$'
    build_match = re.search(build_metadata_pattern, s)
    build = []
    if build_match:
        build = build_match.group(1).split('.')
        s = s[:build_match.start()]

    # Prerelease regex
    prerelease_pattern = r'-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)$'
    prerelease_match = re.search(prerelease_pattern, s)
    prerelease = []
    if prerelease_match:
        prerelease_parts = prerelease_match.group(1).split('.')
        for part in prerelease_parts:
            # Check if it's numeric (no leading zeros unless it's just "0")
            if re.match(r'^[0-9]+$', part):
                if len(part) > 1 and part[0] == '0':
                    raise ValueError(f"Invalid version: leading zeros in numeric identifier '{part}'")
                prerelease.append(int(part))
            elif re.match(r'^[0-9A-Za-z-]+$', part):
                prerelease.append(part)
            else:
                raise ValueError(f"Invalid version: invalid prerelease identifier '{part}'")
        s = s[:prerelease_match.start()]

    # Main version regex
    version_pattern = r'^([0-9]+)\.([0-9]+)\.([0-9]+)$'
    match = re.match(version_pattern, s)
    if not match:
        raise ValueError(f"Invalid version: '{s}'")

    major_str, minor_str, patch_str = match.groups()

    # Check for leading zeros
    if (len(major_str) > 1 and major_str[0] == '0') or \
       (len(minor_str) > 1 and minor_str[0] == '0') or \
       (len(patch_str) > 1 and patch_str[0] == '0'):
        raise ValueError(f"Invalid version: leading zeros in numeric identifier")

    return Version(
        int(major_str),
        int(minor_str),
        int(patch_str),
        prerelease if prerelease else None,
        build if build else None
    )


def parse_final(v: str) -> Version:
    """Parse a version string according to SemVer 2.0.0."""
    return parse_v2(v)


