        return cmp >= 0

    return False


def parse_comparator_v2(s: str) -> Tuple[str, Version, bool, bool, bool]:
    """Parse a comparator string, returning (operator, version, is_partial, minor_wildcard, patch_wildcard)."""
    s = s.strip()

    # Determine operator
    op = '='
    if s.startswith('>='):
        op = '>='
        s = s[2:]
    elif s.startswith('>'):
        op = '>'
        s = s[1:]
    elif s.startswith('<='):
        op = '<='
        s = s[2:]
    elif s.startswith('<'):
        op = '<'
        s = s[1:]
    else:
        if s.startswith('='):
            op = '='
            s = s[1:]

    s = s.strip()

    if not s:
        raise ValueError("Invalid comparator: empty version")

    # Check for wildcards in version
    version_str = s
    minor_wildcard = False
    patch_wildcard = False

    # Parse the original string to detect wildcards
    parts = version_str.split('.')
    if len(parts) > 1 and (parts[1] == '*' or parts[1].lower() == 'x'):
        minor_wildcard = True
    if len(parts) > 2 and (parts[2] == '*' or parts[2].lower() == 'x'):
        patch_wildcard = True

    is_partial = minor_wildcard or patch_wildcard

    # Parse version
    version = parse_version_string(version_str)

    return (op, version, is_partial, minor_wildcard, patch_wildcard)


def satisfies_with_partial(version: Version, op: str, comparator_version: Version, 
                           minor_wildcard: bool, patch_wildcard: bool) -> bool:
    """Check if version satisfies the comparator with partial version handling."""
    major = comparator_version.major
    minor = comparator_version.minor
    patch = comparator_version.patch

    # Handle different cases based on wildcards

    # Case 1: major only wildcard (e.g., "1.x" where minor/patch are 0 from x)
    if minor_wildcard and patch_wildcard:
        # e.g., "1.x", "1"
        if op == '>=':
            return version.major >= major
        elif op == '>':
            return version.major > major
        elif op == '<=':
            return version.major <= major
        elif op == '<':
            return version.major < major
        else:  # =
            return version.major == major and version.minor == 0 and version.patch == 0

    # Case 2: minor wildcard, patch not wildcard (e.g., "1.2.x", "1.2")
    elif minor_wildcard:
        # e.g., "1.2.x", "1.2"
        if op == '>=':
            return (version.major == major and version.minor == minor) or \
                   (version.major > major or (version.major == major and version.minor > minor))
        elif op == '>':
            if minor == 0:
                return version.major > major
            else:
                return (version.major == major and version.minor > minor) or \
                       (version.major > major)
        elif op == '<=':
            return (version.major == major and version.minor == minor) or \
                   (version.major < major or (version.major == major and version.minor < minor))
        elif op == '<':
            if minor == 0:
                return version.major < major
            else:
                return (version.major == major and version.minor < minor) or \
                       (version.major < major)
        else:  # =
            return version.major == major and version.minor == minor and version.patch == 0

    # Case 3: no wildcards (exact version)
    else:
        return satisfies_version(version, op, comparator_version)


def parse_range(rng: str) -> List[List[Tuple[str, Version, bool, bool, bool, int, int, int]]]:
    """Parse a range string into a list of comparator sets."""
    rng = rng.strip()
    if not rng:
        raise ValueError("Empty range")

    # Split into sets by ||
    set_strings = rng.split('||')

    comparator_sets = []
    for set_str in set_strings:
        set_str = set_str.strip()
        if not set_str:
            raise ValueError("Empty comparator set")

        # Check for * or empty set
        if set_str == '*':
            # Matches any version
            # We can represent this as a special case
            comparator_sets.append(None)  # None means universal set
            continue

        # Split into comparators by whitespace
        parts = set_str.split()

        # Check for empty set (should have at least one comparator)
        if not parts:
            raise ValueError("Empty comparator set")

        # Parse comparators
        comparators = []
        for part in parts:
            part = part.strip()
            if not part:
                continue

            # Check for tilde operator
            if part.startswith('~'):
                # Tilde range: ~1.2.3 means >=1.2.3 <1.3.0
                version_str = part[1:]
                version = parse_version_string(version_str)

                # Determine the range based on the version parts
                major = version.major
                minor = version.minor
                patch = version.patch

                # ~1.2.3 means >=1.2.3 <1.3.0
                # ~1.2 means >=1.2.0 <1.3.0
                # ~1 means >=1.0.0 <2.0.0

                if patch != 0:
                    # ~1.2.3 means >=1.2.3 <1.3.0
                    lower = Version(major, minor, patch)
                    upper = Version(major, minor + 1, 0)
                    comparators.append(('>=', lower, False, False, False, 0, 0, 0))
                    comparators.append(('<', upper, False, False, False, 0, 0, 0))
                elif minor != 0:
                    # ~1.2 means >=1.2.0 <1.3.0
                    lower = Version(major, minor, 0)
                    upper = Version(major, minor + 1, 0)
                    comparators.append(('>=', lower, False, False, False, 0, 0, 0))
                    comparators.append(('<', upper, False, False, False, 0, 0, 0))
                else:
                    # ~1 means >=1.0.0 <2.0.0
                    lower = Version(major, 0, 0)
                    upper = Version(major + 1, 0, 0)
                    comparators.append(('>=', lower, False, False, False, 0, 0, 0))
                    comparators.append(('<', upper, False, False, False, 0, 0, 0))

            # Check for caret operator
            elif part.startswith('^'):
                # Caret range: ^1.2.3 means >=1.2.3 <2.0.0
                version_str = part[1:]

                # Check for wildcards in version string
                minor_wildcard = False
                patch_wildcard = False
                if 'x' in version_str.lower() or '*' in version_str:
                    parts_list = version_str.split('.')
                    if len(parts_list) > 1 and (parts_list[1] == '*' or parts_list[1].lower() == 'x'):
                        minor_wildcard = True
                    if len(parts_list) > 2 and (parts_list[2] == '*' or parts_list[2].lower() == 'x'):
                        patch_wildcard = True

                version = parse_version_string(version_str)

                # Determine the range based on the version parts
                major = version.major
                minor = version.minor
                patch = version.patch

                # ^1.2.3 means >=1.2.3 <2.0.0
                # ^0.2.3 means >=0.2.3 <0.3.0
                # ^0.0.3 means >=0.0.3 <0.0.4
                # ^1.2.x means >=1.2.0 <2.0.0
                # ^0.0.x means >=0.0.0 <0.1.0
                # ^0.x means >=0.0.0 <1.0.0

                if major == 0:
                    if minor == 0:
                        if patch != 0:
                            # ^0.0.3 means >=0.0.3 <0.0.4
                            lower = Version(major, minor, patch)
                            upper = Version(major, minor, patch + 1)
                            comparators.append(('>=', lower, False, False, False, 0, 0, 0))
                            comparators.append(('<', upper, False, False, False, 0, 0, 0))
                        else:
                            # ^0.0.x means >=0.0.0 <0.1.0
                            lower = Version(major, minor, 0)
                            upper = Version(major, minor + 1, 0)
                            comparators.append(('>=', lower, False, False, False, 0, 0, 0))
                            comparators.append(('<', upper, False, False, False, 0, 0, 0))
                    else:
                        # ^0.2.3 means >=0.2.3 <0.3.0
                        # ^0.2.x means >=0.2.0 <0.3.0
                        if patch_wildcard:
                            lower = Version(major, minor, 0)
                        else:
                            lower = Version(major, minor, patch)
                        upper = Version(major, minor + 1, 0)
                        comparators.append(('>=', lower, False, False, False, 0, 0, 0))
                        comparators.append(('<', upper, False, False, False, 0, 0, 0))
                else:
                    # ^1.2.3 means >=1.2.3 <2.0.0
                    # ^1.2.x means >=1.2.0 <2.0.0
                    if minor_wildcard:
                        lower = Version(major, minor, 0)
                    else:
                        lower = Version(major, minor, patch)
                    upper = Version(major + 1, 0, 0)
                    comparators.append(('>=', lower, False, False, False, 0, 0, 0))
                    comparators.append(('<', upper, False, False, False, 0, 0, 0))

            # Check for hyphen range
            elif ' - ' in part:
                hyphen_parts = part.split(' - ')
                if len(hyphen_parts) != 2:
                    raise ValueError(f"Invalid hyphen range: '{part}'")

                lower_str = hyphen_parts[0].strip()
                upper_str = hyphen_parts[1].strip()

                if not lower_str or not upper_str:
                    raise ValueError(f"Invalid hyphen range: '{part}'")

                # Parse lower version
                lower_version = parse_version_string(lower_str)

                # Parse upper version
                upper_version = parse_version_string(upper_str)

                # For partial upper bound, it's exclusive of the next: "1.2.3 - 2.3" is <2.4.0
                major_upper = upper_version.major
                minor_upper = upper_version.minor
                patch_upper = upper_version.patch

                # Check for wildcards in upper version
                minor_wildcard_upper = False
                patch_wildcard_upper = False
                parts_upper = upper_str.split('.')
                if len(parts_upper) > 1 and (parts_upper[1] == '*' or parts_upper[1].lower() == 'x'):
                    minor_wildcard_upper = True
                if len(parts_upper) > 2 and (parts_upper[2] == '*' or parts_upper[2].lower() == 'x'):
                    patch_wildcard_upper = True

                if minor_wildcard_upper or patch_wildcard_upper:
                    # Expand upper bound to next version
                    if minor_upper == 0 and patch_upper == 0:
                        # e.g., 2 means next is 3.0.0
                        upper_exclusive = Version(major_upper + 1, 0, 0)
                    elif patch_upper == 0:
                        # e.g., 2.3 means next is 2.4.0
                        upper_exclusive = Version(major_upper, minor_upper + 1, 0)
                    else:
                        upper_exclusive = Version(major_upper, minor_upper, patch_upper + 1)

                    # Add lower bound
                    comparators.append(('>=', lower_version, False, False, False, 0, 0, 0))
                    # Add upper bound
                    comparators.append(('<', upper_exclusive, False, False, False, 0, 0, 0))
                else:
                    # Exact upper bound, inclusive
                    # Add lower bound
                    comparators.append(('>=', lower_version, False, False, False, 0, 0, 0))
                    # Add upper bound
                    comparators.append(('<=', upper_version, False, False, False, 0, 0, 0))
            else:
                # Regular comparator
                op, comparator_version, is_partial, minor_wildcard, patch_wildcard = parse_comparator_v2(part)

                # For operators like >, >=, <, <= with partial versions, we need to expand
                if op in ('>', '<', '>=', '<=') and is_partial:
                    major = comparator_version.major
                    minor = comparator_version.minor
                    patch = comparator_version.patch

                    if op == '>=':
                        # >=1.2 means >=1.2.0
                        comparators.append(('>=', comparator_version, is_partial, minor_wildcard, patch_wildcard, major, minor, patch))
                    elif op == '>':
                        # >1.2 means >=1.3.0
                        if minor_wildcard and patch_wildcard:
                            # >1 means >=2.0.0
                            next_version = Version(major + 1, 0, 0)
                        elif minor_wildcard:
                            # >1.2 means >=1.3.0
                            next_version = Version(major, minor + 1, 0)
                        else:
                            # >1.2.3 means >=1.2.4
                            next_version = Version(major, minor, patch + 1)
                        comparators.append(('>=', next_version, False, False, False, 0, 0, 0))
                    elif op == '<=':
                        # <=1.2 means <1.3.0, i.e., <=1.2.999...
                        # We can represent this as < next version
                        if minor_wildcard and patch_wildcard:
                            # <=1 means <2.0.0
                            upper_exclusive = Version(major + 1, 0, 0)
                        elif minor_wildcard:
                            # <=1.2 means <1.3.0
                            upper_exclusive = Version(major, minor + 1, 0)
                        else:
                            # <=1.2.3 means <1.2.4
                            upper_exclusive = Version(major, minor, patch + 1)
                        comparators.append(('<', upper_exclusive, False, False, False, 0, 0, 0))
                    elif op == '<':
                        # <1.2 means <1.2.0
                        if minor_wildcard and patch_wildcard:
                            # <1 means <1.0.0
                            upper_exclusive = Version(major, 0, 0)
                        elif minor_wildcard:
                            # <1.2 means <1.2.0
                            upper_exclusive = Version(major, minor, 0)
                        else:
                            # <1.2.3 means <1.2.3
                            upper_exclusive = comparator_version
                        comparators.append(('<', upper_exclusive, False, False, False, 0, 0, 0))
                    else:
                        comparators.append((op, comparator_version, is_partial, minor_wildcard, patch_wildcard, major, minor, patch))
                else:
                    # Exact version comparison
                    major = comparator_version.major
                    minor = comparator_version.minor
                    patch = comparator_version.patch
                    comparators.append((op, comparator_version, is_partial, minor_wildcard, patch_wildcard, major, minor, patch))

        # Create comparator set
        comparator_sets.append(comparators)

    return comparator_sets


def satisfies(version_str: str, rng: str) -> bool:
    """Check if a version satisfies a range."""
    version = parse_version_string(version_str)

    # Parse the range
    rng = rng.strip()
    if not rng:
        raise ValueError("Empty range")

    # Special case for '*'
    if rng == '*':
        return True

    # Parse range
    comparator_sets = parse_range(rng)

    # Check each comparator set
    for set_comparators in comparator_sets:
        if set_comparators is None:  # Universal set
            return True

        all_match = True
        for op, comparator_version, is_partial, minor_wildcard, patch_wildcard, major, minor, patch in set_comparators:
            # Check satisfaction
            if is_partial:
                # Handle partial versions
                if op == '>=':
                    if compare_versions_for_satisfies(version, comparator_version) < 0:
                        all_match = False
                        break
                elif op == '>':
                    if minor_wildcard and patch_wildcard:
                        # >1 means >=2.0.0
                        if version.major <= major:
                            all_match = False
                            break
                    elif minor_wildcard:
                        # >1.2 means >=1.3.0
                        if version.major < major or (version.major == major and version.minor <= minor):
                            all_match = False
                            break
                    else:
                        # >1.2.3 means >=1.2.4
                        if version.major < major or \
                           (version.major == major and version.minor < minor) or \
                           (version.major == major and version.minor == minor and version.patch <= patch):
                            all_match = False
                            break
                elif op == '<=':
                    # <=1.2 means <1.3.0
                    if minor_wildcard and patch_wildcard:
                        # <=1 means <2.0.0
                        if version.major >= major + 1:
                            all_match = False
                            break
                    elif minor_wildcard:
                        # <=1.2 means <1.3.0
                        if version.major > major or (version.major == major and version.minor >= minor + 1):
                            all_match = False
                            break
                    else:
                        # <=1.2.3 means <1.2.4
                        if version.major > major or \
                           (version.major == major and version.minor > minor) or \
                           (version.major == major and version.minor == minor and version.patch >= patch):
                            all_match = False
                            break
                elif op == '<':
                    # <1.2 means <1.2.0
                    if minor_wildcard and patch_wildcard:
                        # <1 means <1.0.0
                        if version.major >= major:
                            all_match = False
                            break
                    elif minor_wildcard:
                        # <1.2 means <1.2.0
                        if version.major > major or (version.major == major and version.minor >= minor):
                            all_match = False
                            break
                    else:
                        # <1.2.3 means <1.2.3
                        if compare_versions_for_satisfies(version, comparator_version) >= 0:
                            all_match = False
                            break
                else:
                    # = with wildcards
                    if major != 0 and version.major != major:
                        all_match = False
                        break
                    if minor == 0 and patch == 0:
                        # 1 means >=1.0.0 <2.0.0
                        if version.major != major:
                            all_match = False
                            break
                    elif patch == 0:
                        # 1.2 means >=1.2.0 <1.3.0
                        if version.major != major or version.minor != minor:
                            all_match = False
                            break
                    else:
                        # 1.2.3 means exact match
                        if version.major != major or version.minor != minor or version.patch != patch:
                            all_match = False
                            break
            else:
                # Exact version comparison
                if op == '=':
                    if compare_versions_for_satisfies(version, comparator_version) != 0:
                        all_match = False
                        break
                elif op == '<':
                    if compare_versions_for_satisfies(version, comparator_version) >= 0:
                        all_match = False
                        break
                elif op == '>':
                    if compare_versions_for_satisfies(version, comparator_version) <= 0:
                        all_match = False
                        break
                elif op == '<=':
                    if compare_versions_for_satisfies(version, comparator_version) > 0:
                        all_match = False
                        break
                elif op == '>=':
                    if compare_versions_for_satisfies(version, comparator_version) < 0:
                        all_match = False
                        break

        if all_match:
            return True

    return False


def max_satisfying(versions: list[str], rng: str) -> Optional[str]:
    """Return the version that satisfies the range and is the highest."""
    satisfying_versions = []
    for v in versions:
        try:
            if satisfies(v, rng):
                satisfying_versions.append(v)
        except ValueError:
            # Skip invalid versions
            continue

    if not satisfying_versions:
        return None

    # Sort by version precedence and return the highest
    version_objects = []
    for v in satisfying_versions:
        try:
            version_objects.append((v, parse_version_string(v)))
        except ValueError:
            continue

    if not version_objects:
        return None

    # Sort by version in descending order
    version_objects.sort(key=lambda x: x[1], reverse=True)

    # Return the original string
    return version_objects[0][0]
