def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Split a command line into words, implementing a subset of POSIX shell word splitting
    and parameter expansion.
    """
    result = []
    i = 0
    n = len(line)

    # Stack of words being built
    # Each word is a list of string fragments (for concatenation)
    words = []

    # Stack to track current state
    # state = 'unquoted' | 'double' | 'single'
    stack = []

    i = 0
    while i < n:
        char = line[i]

        # Handle state transitions
        if not stack:
            stack.append('unquoted')

        state = stack[-1]

        if state == 'unquoted':
            if char in ' \t\n':
                # Skip whitespace in unquoted state
                i += 1
                continue
            elif char == "'":
                # Start single-quoted string
                stack.append('single')
                i += 1
                continue
            elif char == '"':
                # Start double-quoted string
                stack.append('double')
                i += 1
                continue
            elif char == '\\':
                # Unquoted backslash - escape next char (but newline removal is special)
                if i + 1 < n and line[i+1] == '\n':
                    # Backslash-newline is removed entirely
                    i += 2
                    continue
                elif i + 1 < n:
                    # Escape next character
                    i += 2
                    # Add the escaped character literally
                    # We'll handle this by pushing the escaped character into the current word
                    # For now, we'll need to track that we need to add the escaped char
                    # Let's use a temporary variable approach
                    pass  # We'll handle this below
                else:
                    # Trailing unescaped backslash
                    raise ValueError("trailing unescaped backslash")
            elif char == '$':
                # Start of parameter expansion
                if i + 1 >= n:
                    # $ at end, literal
                    stack.append('unquoted_expansion_literal')
                elif line[i+1] == '{':
                    # ${...}
                    stack.append('unquoted_expansion_brace')
                elif line[i+1].isalnum() or line[i+1] == '_':
                    # $NAME
                    stack.append('unquoted_expansion_name')
                else:
                    # $ not followed by valid name - literal
                    stack.append('unquoted_expansion_literal')
            else:
                # Regular unquoted character
                stack.append('unquoted_normal')
        elif state == 'double':
            if char == '"':
                # End double-quoted string
                stack.pop()
                i += 1
                continue
            elif char == '\\':
                # Check what's next
                if i + 1 < n:
                    next_char = line[i+1]
                    if next_char in '$"\\\n':
                        # Escape these characters
                        stack.append('double_escape')
                    else:
                        # Other backslash stays as is
                        stack.append('double_normal')
                else:
                    # Trailing backslash
                    raise ValueError("trailing unescaped backslash")
            elif char == '$':
                # Parameter expansion in double quotes
                if i + 1 < n and line[i+1] == '{':
                    stack.append('double_expansion_brace')
                elif i + 1 < n and (line[i+1].isalnum() or line[i+1] == '_'):
                    stack.append('double_expansion_name')
                else:
                    stack.append('double_expansion_literal')
            else:
                stack.append('double_normal')
        elif state == 'single':
            if char == "'":
                # End single-quoted string
                stack.pop()
                i += 1
                continue
            else:
                stack.append('single_normal')
        elif state == 'unquoted_normal':
            # We're in unquoted normal mode, adding characters to current word
            if char == "'":
                stack[-1] = 'unquoted'
                stack.append('single')
                i += 1
                continue
            elif char == '"':
                stack[-1] = 'unquoted'
                stack.append('double')
                i += 1
