            elif char == '\\':
                if i + 1 < n and line[i+1] == '\n':
                    # Backslash-newline is removed entirely
                    i += 2
                    continue
                elif i + 1 < n:
                    # Escape next character, just add the next character literally
                    i += 2
                    # Add the escaped character
                    if not words:
                        words.append([])
                    words[-1].append(line[i-1])
