                stack[-1] = 'unquoted'
                if words:
                    # Concatenate the fragments and add to result
                    word = ''.join(words[0])
                    result.append(word)
                    words = []
                i += 1
                continue
            else:
                # Normal character - just add it
                if not words:
                    words.append([])
                words[-1].append(char)
                i += 1
                continue
        elif state == 'unquoted_expansion_literal':
            # We have a literal $ that we need to add
            stack[-1] = 'unquoted'
            # Add $ literally
            if not words:
                words.append([])
            words[-1].append('$')
            # Now continue with normal unquoted processing for next char
            continue
        elif state == 'unquoted_expansion_name':
            # We have $NAME - extract the variable name
            j = i + 1
            name_start = j
            while j < n and (line[j].isalnum() or line[j] == '_'):
                j += 1

            var_name = line[name_start:j]
            i = j

            # Get the variable value
            var_value = env.get(var_name, '')

            # Add to current word (will be split later if unquoted)
            if not words:
