            words[-1].append(var_value)

            # Continue with unquoted state
            stack[-1] = 'unquoted'
            continue
        elif state == 'unquoted_expansion_brace':
            # We have ${...} - parse it
            if i + 1 >= n or line[i] != '{':
                raise ValueError("unterminated ${")

            j = i + 2  # Skip ${
            # Find closing brace
            brace_depth = 1
            while j < n and brace_depth > 0:
                if line[j] == '{':
                    brace_depth += 1
                elif line[j] == '}':
                    brace_depth -= 1
                j += 1

            if brace_depth > 0:
                raise ValueError("unterminated ${")

