    if (ip !~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/) {
        malformed++
        next
    }

    # Find the timestamp in brackets
    timestamp_start = index($0, "[")
    timestamp_end = index($0, "]")

