    timestamp = substr($0, timestamp_start + 1, timestamp_end - timestamp_start - 1)
    if (timestamp !~ /^[0-9]{2}\/[A-Za-z]{3}\/[0-9]{4}:[0-9]{2}:[0-9]{2}:[0-9]{2} [+-][0-9]{4}$/) {
        malformed++
