        for (i = 1; i <= n; i++) {
            word = words[i]
            # Strip leading apostrophes
            while (substr(word, 1, 1) == "'\''") word = substr(word, 2)
            # Strip trailing apostrophes
            while (substr(word, length(word), 1) == "'\''") word = substr(word, 1, length(word)-1)
